  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Carpe (US) Affiliate Program - via Awin', 'https://ui.awin.com/merchant-profile/122750', 'https://ui.awin.com/merchant-profile/122750', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/122750', 'affiliate_network', 'affiliate_program', 'Awin''s own merchant profile for Carpe (US) publishes the program details: commission of 2%-8% (most partners start at 7%, increasing as the partnership strengthens) and a 30-day cookie period. The profile describes Carpe as the fastest growing antiperspirant brand in the US with over 3,000,000 customers and 45,000 5-star reviews. No earnings cap is stated.', 'verified', now());
