  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 11, 8, 7, 4, '{"compensation": "Published range of 2%-8% with most partners starting at 7% - transparent, but recorded null because it is a range, not a single rate.", "contact_access": "Application through Awin; no public creator email found.", "credibility": "Fast-growing US antiperspirant brand claiming 3,000,000+ customers and top-5 category sales on Amazon and Walmart per its Awin profile.", "niche_fit": "Personal-care niche: sweat and odor control products with a clear problem/solution demo format for creators.", "opportunity_availability": "Open application through Awin.", "ugc_evidence": "Awin program profile explicitly recruits partners to share their experience switching to Carpe with their audience."}'::jsonb);
