  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/samsonite/', 'listing', 'compensation', 'Other listings conflict with the 5% figure: Lasso reports 4.75% per sale with a 14-day cookie, Affjumbo reports 3.2%, and LinkApprove reports up to 6%. Because published rates conflict by network and region, the commission rate is recorded as null; the program''s existence across Impact, CJ, Awin and Sovrn is consistent.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 12, 9, 5, 8, 5, '{"niche_fit": "The default name in luggage; suitcases and travel accessories anchor packing, gear-review and travel content.", "ugc_evidence": "Runs publisher programs on several major networks, a route travel bloggers and reviewers already use.", "compensation": "Mid-single-digit rates are reported (roughly 3\u20136% depending on network/region) but they conflict, so no single rate is recorded.", "contact_access": "No public creator contact was found; access is via network applications.", "opportunity_availability": "Programs are listed on multiple networks, though Samsonite notes it works with a limited number of quality sites.", "credibility": "A century-old, publicly traded global luggage company \u2014 about as established as the category gets."}'::jsonb);
