  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dollarflightclub.com/affiliates/', 'official_site', 'affiliate', 'Dollar Flight Club''s own affiliates page states affiliates earn 40% for any Premium Member signups they drive, joining is free, commissions are paid in USD to affiliates worldwide, and top affiliates can win a free flight. The page does not state an earnings cap or a creator count, so both are recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://khrisdigital.com/best-airline-affiliate-programs/', 'listing', 'compensation', 'Third-party roundups mostly corroborate the 40% headline (KhrisDigital and Cuelinks say 40% via Refersion with a 30-day cookie and PayPal payouts), while Lasso claims 50% recurring with a 90-day cookie via Impact. The brand''s own published 40% is used; the network is reported as Refersion by two sources and Impact by Lasso, so both are recorded.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 19, 6, 8, 4, '{"niche_fit": "Cheap-flight alerts are core travel-hack content; the product is a natural fit for deal and itinerary creators.", "ugc_evidence": "The brand''s own page recruits affiliates who place links on websites and social feeds, with a free-flight bonus for top performers.", "compensation": "40% per Premium signup, published on the brand''s own page, is among the highest rates in travel; a third-party 50% claim is documented but not used.", "contact_access": "Application runs through the brand''s own affiliates page; no public program email was published there.", "opportunity_availability": "Free and open to applicants worldwide, though the brand says it prefers regularly publishing creators and manually reviews applications.", "credibility": "A long-running, widely covered flight-deal subscription service with a large member base."}'::jsonb);
