  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'InsureMyTrip Affiliate Partnership Program', 'https://www.insuremytrip.com/about/affiliate-program/', 'https://www.insuremytrip.com/about/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.insuremytrip.com/about/affiliate-program/', 'official_site', 'affiliate', 'InsureMyTrip''s own Affiliate Partnership Program page says affiliates earn a referral fee for every policy purchased through their unique link, signup is free via an online application, and approved affiliates manage links, tracking and payments through their Impact account. The page publishes affiliates@insuremytrip.com for program questions and does not publish a rate, cap or creator count.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/travel-insurance-affiliate-programs/', 'affiliate_network', 'compensation', 'CompareEPC''s network data reports InsureMyTrip paying a flat $7 per verified hit on Impact, while LinkClicky reports a $10 verified hit. Because the flat-fee figures conflict ($7 vs $10) and it is a per-action fee rather than a percentage, commission_rate is recorded as null with the flat-fee model documented here.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 10, 12, 8, 5, '{"niche_fit": "Travel insurance is a standard recommendation in trip-planning, cruising and international-travel content.", "ugc_evidence": "The brand''s own page encourages affiliates to create content about why travel insurance is essential, not just place links.", "compensation": "Pays a flat fee per verified action on Impact (reported at $7\u2013$10), which can outperform small percentage commissions on low policy counts, but the exact figure conflicts between sources.", "contact_access": "Publishes a dedicated affiliate email (affiliates@insuremytrip.com) and an application on its own site.", "opportunity_availability": "Free online application; selected affiliates get Impact tracking and payment access.", "credibility": "A pioneer of travel-insurance comparison, operating for over two decades with millions of travelers served."}'::jsonb);
