  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 8, 4, 6, 4, '{"niche_fit": "Minimalist, sustainable wardrobe staples are a reliable fashion-content category for both men''s and women''s creators.", "ugc_evidence": "Listed with affiliate directories and a Sovrn merchant presence, indicating an active publisher channel.", "compensation": "A 5\u201310% range is reported but no single verified rate or network-published figure could be confirmed, so pay is left unpublished.", "contact_access": "No public creator contact was found, and the network listing itself flags terms as unverified.", "opportunity_availability": "Access appears to run through Sovrn Commerce signup, subject to confirming the merchant is currently active.", "credibility": "A well-known Canadian retailer with a long sustainability track record and national store footprint."}'::jsonb);
