  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fangwallet.com/2025/03/03/monetize-your-website-or-business-effortlessly-with-the-bounce-affiliate-program/', 'listing', 'affiliate', 'FangWallet''s walkthrough of the Bounce Affiliate Program reports a 10% commission on each successful luggage-storage booking (affiliates may instead pass a 10% discount to their audience), monthly payments with no minimum payout, signup via an online form at partner.bounce.com, and a network of 14,000+ locations. No earnings cap or creator count is stated, so both are recorded as unknown.', 'publicly_reported', now());
