  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 13, 5, 9, 4, '{"niche_fit": "Luggage storage is a universal travel pain point \u2014 day-trip, layover and checkout-day content converts naturally.", "ugc_evidence": "The program is pitched directly at bloggers, website owners and social creators, with shareable referral links for social and email.", "compensation": "10% of every booking with monthly payouts and no minimum threshold is clean, creator-friendly economics.", "contact_access": "Signup is a self-serve form on Bounce''s partner platform; no public affiliate email was published in the sources checked.", "opportunity_availability": "Open application with approval and a unique link; usable across social, web and in-person channels.", "credibility": "The category leader in luggage storage with a 4.9/5 app rating and locations in thousands of cities."}'::jsonb);
