  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Blackout Coffee Co Affiliate Program (Social Snowball)', 'https://www.blackoutcoffee.com/pages/affiliate-terms-conditions', 'https://www.blackoutcoffee.com/pages/affiliate-terms-conditions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.blackoutcoffee.com/pages/affiliate-terms-conditions', 'brand_site', 'affiliate', 'Blackout Coffee''s own Affiliate Program Terms & Conditions (effective September 14, 2026) state the program is powered by Social Snowball and that affiliates earn a 15% commission on the product subtotal of each qualifying order (after discounts, excluding shipping, taxes and gift cards); subscription orders pay commission on the first order only. Referral links/codes give customers 20% off their first order; commissions are held 30 days, paid monthly between the 5th and 20th, with a $100 minimum payout. The terms state no earnings cap, so the cap is recorded as unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.blackoutcoffee.com/pages/affiliate-terms-conditions', 'brand_site', 'contact', 'The terms page publishes the program contact: ''Questions about the Program: affiliates@howloo.com'' (Howloo, Inc. is Blackout Coffee''s parent company).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.blackoutcoffee.com/pages/affiliate-terms-conditions', 'brand_site', 'ugc_collab', 'The terms expressly invite promotion through affiliates'' own social media, websites, email lists, video channels and podcasts, and grant the brand a royalty-free license to repost affiliate content tagged @blackoutcoffeeco or featuring its products with credit — a structured UGC/creator route, not gifting-only.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 16, 13, 8, 4, '{"compensation": "15% of product subtotal on every qualifying order, published in the brand''s own terms (first-order-only on subscriptions).", "contact_access": "A published program email (affiliates@howloo.com) plus the full terms page \u2014 top band.", "credibility": "Established DTC roaster with a formal, dated terms document and US-only shipping clearly stated.", "niche_fit": "Coffee is a core food-drink creator niche and the brand''s terms are written for social, video and podcast promotion.", "opportunity_availability": "Open application under published terms, though the brand may approve or reject at its discretion; $100 payout minimum.", "ugc_evidence": "A formal affiliate program with published terms, creator promotion rights and a brand repost license for affiliate content."}'::jsonb);
