  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nume Affiliate Partner Program', 'https://wearenume.com/pages/nume-affiliate-program', 'https://wearenume.com/pages/nume-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wearenume.com/pages/nume-affiliate-program', 'brand_site', 'affiliate', 'Nume''s own affiliate page publishes a three-tier structure: Starter (0–15 sales) earns 35% on first subscriptions, 20% on one-time purchases and 10% on subscription renewals; Partner (15–50 sales) 45%/25%/15%; Elite (50+ sales) 60%/35%/20%. The headline ''up to 60%'' is a tier ceiling, and because no single rate applies, commission_rate is recorded as null with the full tier table documented here. No earnings-cap statement appears on the page, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wearenume.com/pages/nume-affiliate-program', 'brand_site', 'ugc_collab', 'Partners receive free product before promoting, a creative kit (photos, b-roll, talking points), a personalized landing page and whitelisting opportunities; the page states no minimum followers are required and payouts are monthly via a real-time dashboard.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 14, 12, 9, 3, '{"compensation": "Published tiers are generous (Starter already 35% on first subscriptions, 10% on renewals), but the rate is tier- and sale-type-dependent, so no single rate is recorded.", "contact_access": "A public application form on the brand''s own page with a stated 24-hour partnerships-team response; no direct email published.", "credibility": "Young DTC brand; program terms are published in detail on its own site, but it lacks the retail footprint of larger entries.", "niche_fit": "Women''s wellness supplements are a strong health-creator niche, and the NFC health platform gives creators a distinctive story.", "opportunity_availability": "Open application with no minimum follower requirement, reviewed within 48 hours per the page.", "ugc_evidence": "A structured partner program with free product, creative kit, branded landing pages and whitelisting \u2014 built for creators."}'::jsonb);
