  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/atlas-coffee-club-affiliate-program', 'listing', 'affiliate', 'LinkApprove''s program page (reviewed August 18, 2026) states the Atlas Coffee Club program pays a flat $14 bounty per new subscription with a 30-day cookie, open to US creators/publishers from 1,000 followers with no separate brand application. Other sources conflict — a roundup lists a $10 flat fee, another lists 8% per sale, others cite 10–15% or up to 25% — so commission_rate is recorded as null (no percentage rate applies) with the flat-bounty figure and the conflict documented here. No fetched source states an earnings cap, so the cap is unknown.', 'publicly_reported', now());
